#!/usr/bin/env python3
"""Publish ONLY completed source-linked VideoSham video evaluation, no media.

The original Vimeo clips and author-altered videos are noncommercial Adobe
licensed, stay in /data/var. Labels are author EDIT TYPE, not subjective
natural video freeze defects. The complete original 19 temporal and 19 other
edited controls selected with source group and hash, frozen before image scores.
All altered and original MP4s verified against public release ZIP CRC+size.
Model-free no-reference and reference-aware pHash strategies report TP FP FN TN,
source coverage, abstentions, codec/duration confounds and CPU resource scope.
"""
from pathlib import Path
import json,hashlib,statistics,collections
from scipy.stats import beta
SRC=Path('/data/var/perceptual-independent-20261024/videosham-20261025')
ROOT=Path(__file__).resolve().parents[2]/'docs/research'
OUT=ROOT/'perceptual-videosham-real-temporal-editor-control-2026-10-25.json'
DOC=ROOT/'perceptual-videosham-real-temporal-evidence-2026-10-25.md'


def load(name):
 raw=(SRC/name).read_bytes();return json.loads(raw),hashlib.sha256(raw).hexdigest()

def ci(k,n):
 if not n:return None
 return [round(float(beta.ppf(.025,k,n-k+1)) if k else 0,4),round(float(beta.ppf(.975,k+1,n-k)) if k<n else 1,4)]

def pct(v):return 'unavailable' if v is None else f'{v*100:.1f}%'

def main():
 if OUT.exists() or DOC.exists():print('ALREADY_PUBLISHED_NO_DUPLICATE');return
 select,hsel=load('source_selection_original_38_video_pairs_20261025.json')
 receipts,hreceipts=load('selected_video_member_receipts_20261025.json')
 src,hfeatures=load('38_real_clip_source_temporal_pixels_frozen_20261025.json')
 scores,hscore=load('38_real_manually_assigned_video_temporal_edit_scores_20261025.json')
 ff,hff=load('videosham_official_ffmpeg_freezedetect_author_edit_scores_20261025.json')
 assert select['source_pairs_expected']==scores['n_independent_source_vimeo_snippets']==38
 assert select['n_temporal_authored']==scores['n_temporal_author_labels']==19
 assert select['n_other_authored']==scores['n_other_edited_source_controls']==19
 assert len(receipts['completed'])==76
 assert src['status']=='complete' and len(src['cases'])==38
 assert scores['frozen_real_video_pixel_feature_SHA256']==hfeatures
 assert scores['source_clip_selection_sha256']==hsel
 assert receipts['selection_sha256']==hsel
 assert scores['decoding_failures']==1
 assert ff['result']['scored_n']==38 and ff['result']['TP']==7 and ff['result']['FP']==12
 nonmissing=sum(a['original']['signals']['frame_count']+a['processed']['signals']['frame_count'] for a in src['cases'].values() if a['status']=='complete')
 methodnames=['no_ref_hold','no_ref_jerk','no_ref_combined','reference_aware','duration_only_CONFOUNDED_NOT_VISUAL']
 rows=[];outcome={}
 for name in methodnames:
  r=scores['methods'][name]
  npos=r['TP']+r['FN'];nneg=r['TN']+r['FP']
  assert npos+r['abstained_positive']==19 and nneg+r['abstained_other_edit_controls']==19
  outcome[name]={**r,'exact_binomial95_on_conditional_recall':ci(r['TP'],npos),'exact_binomial95_on_conditional_false_alarm_rate':ci(r['FP'],nneg),'not_an_independent_camera_family_human_rating':True}
  rows.append(f"| {name.replace('_',' ')} | {r['TP']}/{npos} | {r['FP']}/{nneg} | {r['FN']} | {r['abstained_positive']} positive and {r['abstained_other_edit_controls']} control | {pct(r['continuous_roc_auc'])} |")
 f=ff['result'];N=19
 outcome['official_ffmpeg_freezedetect']={'tested':f['scored_n'],'TP':f['TP'],'FP':f['FP'],'FN':f['FN'],'TN':f['TN'],'abstained_positive':f['abstained_temporal_positive'],'abstained_other_edit_controls':f['abstained_other_edited_control'],'continuous_roc_auc':f['event_count_AUROC'],'source_clip_bootstrap95':f['source_clip_bootstrap95'],'exact_binomial95_on_conditional_recall':ci(f['TP'],N),'exact_binomial95_on_conditional_false_alarm_rate':ci(f['FP'],N),'not_an_independent_camera_family_human_rating':True}
 rows.append(f"| Official FFmpeg freezedetect, minus fifty decibels, minimum 0.12 seconds | {f['TP']}/19 | {f['FP']}/19 | {f['FN']} | none | {pct(f['event_count_AUROC'])} |")
 src_sources=collections.Counter(r['author_manipulation_category'] for r in scores['case_original_ids_and_truth'])
 report={'date':'2026-10-25','status':'PARTIAL: tested author intentional temporal edit categories on authentic real-video sources; no qualified universal natural video stutter/judder or subjective physics quality judge','dataset':'Adobe VideoSham 2022 author-edited Vimeo original media; publicly published research sample of 352 edits, scoped to release Part1 19 temporal and 19 other edits','license':'Adobe Research License 1.1a noncommercial academic research; never redistribute third-party source video through public project Git','upstream':'https://github.com/adobe-research/VideoSham-dataset','source_hashes':{'immutable_author_labels_and_selection':hsel,'76_video_extract_source_size_crc_and_sha':hreceipts,'38_complete_pair_pixel_features_frozen_before_labels':hfeatures,'edited_vs_other_author_category_labels_score':hscore,'official_ffmpeg_frozen_author_label_comparison':hff},'selection':{'source_release':'GitHub original v1.0 first public original/processed archive pair','independent_original_source_clip_families':38,'author_temporal_intent_positive_pairs':19,'author_other_edit_controls_pairs':19,'original_and_edited_video_files_total':76,'total_expected_download_mb':select['approx_total_paired_download_mb'],'source_category_distribution':dict(src_sources),'no_source_visual_features_used_for_label_selection':True},'resource':{'ffmpeg_original_and_edited_native_fps_gray_128x72_frames_fully_decoded':nonmissing,'GPU_used':False,'actual_video_model_inference_used':False,'ffmpeg_one_thread_nice':True,'raw_restricted_video_media_in_Git':False,'cpu_feature_seconds_this_last_continuation':src.get('processing_elapsed_seconds'),'peak_runtime_RSS_KB':src.get('peak_rss_kb')},'predeclared_detectors':src['config'],'comparisons':outcome,'official_ffmpeg_source_detector_frozen_parameters':ff['filter'],'original_source_intention_breakdown':scores['by_authored_edit_class'],'why_this_does_not_prove_objectionable_video_quality':['Author categories label intentional frame manipulation, which may be aesthetically appropriate and not a human visual defect, unlike production stutter.','No precise human-confirmed altered frame interval references, so temporal localization precision/F1 cannot be computed.','Temporal positives and non-temporal edited controls are editorial categories; other edits and reencodings can cause motion/appearance changes and temporal control false alarms.','All selected clips came from first release half and possibly correlated original Vimeo content; 38 source clips not 38 independent camera families.','Reference-aware frame matching requires access to actual associated original source; where perceptual hashes disagree it must abstain instead of marking good.','A simple duration ratio baseline may perform well for author speed changes without seeing pixels, and should be reported as a confound, not a quality analyzer.','Benchmark size nineteen per class means even no observed false positives is too weak for near-perfect high-stakes specificity.','A method comparison on this dataset is model selection; another untouched video source group is needed for unbiased deployment acceptance.'],'role_for_actual_production':'Use original source/video hashes, exact approved edit/hold timeline and native PTS first, then frame content comparison when exact final approved reference is available, use no-reference freeze/flow as candidate trigger only; ordinary optical flow and visual LLM confidence cannot certify physical plausibility, object realism or stutter intent.'}
 OUT.write_text(json.dumps(report,indent=2)+'\n')
 doc=f'''# Video perceptual analyzer research: original third-party editor-labeled temporal manipulations\n\n**Source-tested 25 October 2026; research state PARTIAL.** This experiment addresses the main previously missing empirical control: no-reference image frame-change and source-reference matching must be tested on *real videos edited by others*, rather than only unit fixtures and intentional local frame copying. Source [Adobe VideoSham](https://github.com/adobe-research/VideoSham-dataset), original authored video-manipulation dataset and exact released original-vs-processed MP4 pairs, research license **Adobe Research License version 1.1a, noncommercial**. No original video, thumbnails or human free-text editor instructions were committed to the SWAAG source project.\n\nThe public first archive contains **nineteen author-assigned frame duplication, dropping, reversal and speed-change videos**. Before video content analysis, all nineteen were selected along with **nineteen different source-video families bearing only other author-assigned edits**, stratified across audio, text, added/removed objects and background/color changes. Each selected manipulated file is paired with its own authentic unedited Vimeo footage. All **seventy-six** individual source MP4s were extracted via byte-range ZIP access, verified against original published member CRC32 and exact source byte counts, and independently hashed. The original archive is over two gigabytes; approximately **{select['approx_total_paired_download_mb']} megabytes** of selected media were actually required, stored under an isolated research data directory. Selection did **not** examine video features, labels were only joined after the predictor outputs froze, and no production Nitro video/render was touched.\n\n## Direct original author-edit positives, false control flags and abstentions\n\nSource labels are author instructions to make edits, not independent human subjective verdicts about objectionable stutter or overall production quality. The nineteen **other processed edits** are important: they are not simply identical unedited clips, so a detector that flags every encoded or altered clip will accumulate false alarms. The methods and thresholds below were declared before scoring: no-reference near-identical frame runs bracketed by motion; no-reference adjacent frame-change spikes; their OR; frame-wise 64-bit DCT perceptual-hash matching against the exact *related unedited source video*, where less than one-quarter confident matching abstains; and a clearly marked **duration-only metadata confound**. All video pixels were actually decoded at native FPS, then resized to 128 by 72 grayscale for analysis; no GPU or learned VLM was used.\n\n| Frozen original-footage method | Temporal editor categories found | False flags on other processed edits | Missed categories | Abstentions | Source-label AUROC (not human quality) |\n|---|---:|---:|---:|---:|---:|\n'''+"\n".join(rows)+"\n\n"
 doc+='''**Direct externally authored reference-control result:** the fixed no-reference motion/hold OR signal detected **2 of 18 scorable** temporal editor cases, with **2 false alerts of 19** other-edited source controls, and had one predeclared decode-limit abstention. Official FFmpeg `freezedetect` at **minus 50 decibels and minimum 0.12 seconds** detected **7 of 19** temporal edits, but falsely flagged **12 of 19** non-temporal edited controls; its event-count ROC AUC was approximately **0.454**. This cannot pass a general freeze/judder release gate. The DCT perceptual-source matching method identified **17 of 18 scorable** temporal edits but falsely flagged **9 of 13** scorable controls, with **one positive and six other-control abstentions**; its conditionally computed AUROC around **0.915** reflects high sensitivity to original-frame deviation, not selectivity for undesired temporal errors. The original native **video duration ratio alone** identified **15 of 18** edit cases with **no false control flags** and an ROC AUC about **0.956**. This duration advantage is a **construction confound**, not a measured visual capability.

The companion `perceptual-videosham-real-temporal-editor-control-2026-10-25.json` retains the exact TP, FP, FN and TN and predeclared continuous-score AUROC, source-type subgroup counts, decode and reference-match abstentions, and source-clip bootstrap/exact binomial intervals. An AUROC score merely ranks the *author's editorial manipulation type* and does not imply that a video visually failed or passed review. Under a sample of nineteen positive and nineteen other edits, uncertainty is substantial; this cannot justify one-hundred-percent safety even for a method with no observed false alarms. Do **not** conflate generator-sourced changes, source encode/resolution artifacts or slow artistic edits with unintended rendering playback faults.\n\n## What changes the immediately usable visual testing default?\n\nWhen the original footage, approved final frame sequence and allowed holds/cuts are known, a reference-aware temporal check is semantically stronger than a generic detector that simply notices static or abrupt frames. But a frame-level reference must be checked for source identity, FPS and content matching; if a video has been cropped, re-encoded or substantially changed, the detector can and should **abstain**. For screenshot-only video, a frame-difference/flow/freeze check can nominate time intervals for actual visual inspection but cannot infer whether the freeze is editorial or unauthorized. Duration/fps alone can predict an author speed-change task but is categorically not perceptual evidence.\n\nThe owner's wider established evidence remains: exact finished warehouse and dock encoded timestamps can be correct while the warehouse has an intentional still-camera ending; Spotlight low-level motion peak detection often approaches the random-time baseline on real annotated synthetic-generation motion faults; photoindustrial CLIP and coarse mesh overlap fail semantic missing-part detection; GUI DOM client/scroll and real source rectangle geometry can prove narrow layout properties while image-only CLIP and OCR return high false alarm rates; the best archived source-diagram VLM answers under three-quarters of true structure questions. Thus a multi-tier toolset is justified, but no universal image/video model currently tested is safe as the release gate.\n\n**Outstanding decisive test:** naturally occurring captured/rendered video playback stalls or undesired camera judder, paired with genuinely clean same-fps/codec controls and independent human frame-accurate labels. [LIVE Mobile Stall II](https://www.colorado.edu/lab/live/live-public-domain-subjective-mobile-stall-video-database-ii) and original LIVE frame-freeze recordings provide higher-quality human subjective data, but their access path requires a form and was not silently used. The CSVTED public [source dataset](https://huggingface.co/datasets/CardiffVisualComputing/CSVTED) includes real source recordings with author inserted, deleted or duplicated frames, but the total release is around forty-four gigabytes and was not needed here. Neither this editorial-control benchmark nor its fixed codec/fps can substitute for naturally occurring unplanned faults. The previously denied other-video result retrievals remain denied, with no retry or workaround.\n\nAll source media remains separate from Git. Research original source labels, source extracted images, model checkpoints and older failures were not overwritten. No calendar events, publishing, production rendering, shared GPU model service or other agent project were modified. **Status PARTIAL.**\n'''
 DOC.write_text(doc)
 print('VIDEO_SHAM_COMPACT_SCIENTIFIC_REPORT_PUBLISHED',OUT.stat().st_size,'BYTES','MD_BYTES',DOC.stat().st_size,'META_FRAME_COUNT',nonmissing,'SOURCE_38',len(scores['case_original_ids_and_truth']))
if __name__=='__main__':main()
